$('opening').textContent=cfg.opening;$('second-copy').textContent='There is something special about you, '+cfg.recipient+'.';$('third-copy').textContent=cfg.anniversaryDate?'Our story began on '+new Date(cfg.anniversaryDate+'T12:00:00').toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'})+'. I made this little memory just for you.':'I made this little memory just for you. Ready?';$('cover-icon').textContent=cfg.icon;$('song-title').textContent=cfg.recipient;$('closing').textContent=cfg.closing;$('signoff').textContent='— From '+cfg.creator+' ♡';if(cfg.motion==='horror'){document.body.style.background='#09090d';$('ending-icon').textContent='👻';$('closing').textContent=cfg.closing||'GOTCHA!';$('signoff').textContent='You really thought that was the end? 😈';if(cfg.endingVideo){const prank=$('prank-video');prank.src=cfg.endingVideo;prank.classList.remove('hidden');prank.style.display='block';prank.controls=true;prank.playsInline=true;prank.style.width='100%';prank.style.maxHeight='58vh';prank.style.borderRadius='16px';prank.style.margin='16px 0';$('ending-card').style.background='linear-gradient(145deg,#191820,#302333)';$('ending-card').style.color='#fff';$('closing').style.color='#ff647c';$('signoff').style.color='#f4d9e0';}}if(cfg.motion==='qa'){$('second-copy').textContent='Ready for a few questions? Answer honestly…';$('third-copy').textContent='Every answer reveals a little more about your connection.';$('cover-icon').textContent='💞';}
if(cfg.motion==='qa'){const qa=$('qa-experience');document.querySelectorAll('.scene,#final').forEach(el=>el.style.display='none');qa.style.display='flex';const prompts=[{q:'Are dance.play().catch(()=>{});you sure? 💗',hint:'Really? Give it another thought…'},{q:'Think again! 🙈',hint:'That No button is not so easy to catch! 😜'},{q:'Are you really, really sure? 💞',hint:'Your heart might know the answer…'},{q:'Last chance… 💘',hint:'One last try before you change your mind!' }];let noCount=0;const qTitle=$('qa-question'),qHint=$('qa-hint'),no=$('qa-no'),yes=$('qa-yes'),card=document.querySelector('.qa-card'),dance=$('qa-dance-video');const LOVE_QA_DANCE_VIDEO_URL='https://mementosuprise.netlify.app//love-yes-dance.mp4';function moveNo(e){if(e)e.preventDefault();noCount++;if(noCount===1){qTitle.textContent=prompts[0].q;qHint.textContent=prompts[0].hint;}else{const prompt=prompts[Math.min(noCount-1,prompts.length-1)];qTitle.textContent=prompt.q;qHint.textContent=prompt.hint;}const parent=no.parentElement;const maxX=Math.max(35,(parent.clientWidth-no.offsetWidth)/2);const maxY=34;const x=Math.round((Math.random()*2-1)*maxX);const y=Math.round((Math.random()*2-1)*maxY);no.style.transform='translate('+x+'px,'+y+'px) rotate('+(Math.random()*18-9)+'deg)';qHint.textContent += ' 🏃💨';}no.addEventListener('pointerenter',moveNo);no.addEventListener('pointerdown',moveNo);no.addEventListener('touchstart',moveNo,{passive:false});no.addEventListener('click',moveNo);yes.addEventListener('click',()=>{qTitle.textContent='I’ve already known! 🥰💖';qHint.textContent='Hehe, I knew you would say yes! You cannot hide your feelings from me. 💕';$('qa-bunny').textContent='💞✨💗';card.classList.add('is-success');document.querySelector('.qa-buttons').style.display='none';if(LOVE_QA_DANCE_VIDEO_URL && !LOVE_QA_DANCE_VIDEO_URL.includes('YOUR-WEBSITE-DOMAIN')){dance.src=LOVE_QA_DANCE_VIDEO_URL;dance.style.display='block';}});}if(cfg.anniversaryDate){const d=new Date(cfg.anniversaryDate+'T12:00:00');const days=Math.max(0,Math.floor((new Date().setHours(12,0,0,0)-d.getTime())/86400000));$('special-date').textContent='SINCE '+d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})+' · '+days+' DAYS TOGETHER';}if(cfg.audio)audio.src=cfg.audio;
function showScene(n){document.querySelectorAll('.scene').forEach(s=>s.classList.remove('active'));$('scene'+n)?.classList.add('active')}
