function buildPhotos(){const box=$('photos');box.replaceChildren();photoData.forEach((src,i)=>{const img=document.createElement('img');img.alt='Memory '+(i+1);img.loading=i===0?'eager':'lazy';img.src=src;img.className=i===0?'on':'';box.appendChild(img)});if(photoData.length){document.body.classList.add('with-photos');$('final').style.background='#242448'}}
let messageSwapTimer=null;function showLine(i){if(!messages.length)return;const safeIndex=Math.max(0,Math.min(i,messages.length-1));if(safeIndex===lineIndex)return;lineIndex=safeIndex;const panel=document.querySelector('.lyric');if(messageSwapTimer)clearTimeout(messageSwapTimer);panel.classList.remove('content-enter');panel.classList.add('content-exit');messageSwapTimer=setTimeout(()=>{ $('verse').textContent=String(safeIndex+1).padStart(2,'0');$('message').textContent=messages[safeIndex];$('support').textContent='— '+({Relationship:'with all my love',Friendship:'always in your corner',Family:'with all my gratitude',Celebration:'cheering you on', 'Personal Growth':'keep becoming'}[cfg.category]||'made with care')+' —';panel.classList.remove('content-exit');void panel.offsetWidth;panel.classList.add('content-enter');messageSwapTimer=null;},reduced?0:220)}
function updateFromTime(){const t=cfg.audio?(audio.currentTime||0):(Date.now()-experienceStartedAt)/1000;const duration=Number.isFinite(audio.duration)&&audio.duration>0?audio.duration:Math.max(42,messages.length*5);const next=Math.min(messages.length-1,Math.floor(t/5)%messages.length);if(next!==lineIndex)showLine(next);if(photoData.length){const pi=Math.floor(t/6)%photoData.length;if(pi!==photoIndex){[...$('photos').children].forEach((img,i)=>img.classList.toggle('on',i===pi));photoIndex=pi}}$('progress').style.width=Math.max(0,Math.min(100,t/duration*100))+'%';$('time').textContent=formatTime(t);}
