$('next1').addEventListener('click',()=>showScene(2));$('next2').addEventListener('click',()=>showScene(3));$('reveal').addEventListener('click',()=>cfg.countdown?beginCountdown():openFinal());$('play').addEventListener('click',()=>audio.play().then(()=>{$('play').style.display='none'}).catch(()=>{$('play').style.display='block'}));$('pause').addEventListener('click',()=>{if(!cfg.audio)return;if(audio.paused){audio.play().then(()=>{$('pause').textContent='Pause'}).catch(()=>{$('play').style.display='block'})}else{audio.pause();$('pause').textContent='Resume'}});$('restart-audio').addEventListener('click',()=>{if(cfg.audio){audio.currentTime=0;audio.play().then(()=>{$('pause').textContent='Pause'}).catch(()=>{$('play').style.display='block'});updateFromTime()}});audio.addEventListener('timeupdate',updateFromTime);audio.addEventListener('seeked',updateFromTime);audio.addEventListener('loadedmetadata',updateFromTime);audio.addEventListener('play',()=>{$('pause').textContent='Pause'});audio.addEventListener('pause',()=>{$('pause').textContent='Resume'});audio.addEventListener('ended',()=>{updateFromTime();finishExperience()});audio.addEventListener('error',()=>{$('play').style.display='block';$('play').textContent='Soundtrack unavailable — try again'});
$('replay').addEventListener('click',()=>{const prank=$('prank-video');if(prank){prank.pause();try{prank.currentTime=0}catch{}}stopCountdown();if(slideshowTimer){clearInterval(slideshowTimer);slideshowTimer=null}audio.pause();try{audio.currentTime=0}catch{}lineIndex=-1;photoIndex=-1;ended=false;if(messageSwapTimer){clearTimeout(messageSwapTimer);messageSwapTimer=null}$('final').style.display='none';$('final').style.visibility='visible';$('ending').style.display='none';$('play').style.display='none';$('progress').style.width='0%';$('time').textContent='00:00';showScene(1)});
